// --- Constants that have to stay const ----------------------------------------------------------
// ND1804 warns that a public const is inlined into consumers, so a later value change does not reach
// them. These three are kept const on purpose; the other public constants became static readonly.
[assembly: SuppressMessage("NDepend", "ND1804:AvoidPubliclyVisibleConstantFields", Target = "Stride.CommunityToolkit:Stride.CommunityToolkit.Engine.CameraDefaults.MainCameraName", Justification = "Optional-parameter default of the Add*Camera and GetCameraEntity overloads, and C# requires a compile-time constant there. A consumer keeping the value it was compiled against still finds the camera it created with it.")]
[assembly: SuppressMessage("NDepend", "ND1804:AvoidPubliclyVisibleConstantFields", Target = "Stride.CommunityToolkit:Stride.CommunityToolkit.Engine.ScreenshotCapture.OutputPathVariable", Justification = "Environment-variable name, i.e. a contract with whoever launches the process; a consumer keeping the name it was compiled against is the correct behaviour.")]
[assembly: SuppressMessage("NDepend", "ND1804:AvoidPubliclyVisibleConstantFields", Target = "Stride.CommunityToolkit:Stride.CommunityToolkit.Engine.ScreenshotCapture.FrameVariable", Justification = "Environment-variable name, i.e. a contract with whoever launches the process; a consumer keeping the name it was compiled against is the correct behaviour.")]
[assembly: SuppressMessage("NDepend", "ND1805:FieldsShouldBeDeclaredAsPrivate", Target = "Stride.CommunityToolkit.DebugShapes:Stride.CommunityToolkit.DebugShapes.Code.ImmediateDebugRenderObject", Scope = "deep", Justification = "instanceOffsets/primitivesToDraw(+NoDepth) are passed by ref into DebugPrimitiveRenderer.DrawPrimitives every frame; a property cannot be passed by ref, and copying the Primitives counter struct per draw would defeat the point of the ref.")]
