[assembly: SuppressMessage("NDepend", "ND1901:AvoidNonReadOnlyStaticFields", Target = "Stride.CommunityToolkit.ImGui:Stride.CommunityToolkit.ImGui.PerfMonitor._threadStaticMonitor", Justification = "Owner marker for the thread-static cache.")]
[assembly: SuppressMessage("NDepend", "ND1902:AvoidStaticFieldsWithAMutableFieldType", Target = "Stride.CommunityToolkit.ImGui:Stride.CommunityToolkit.ImGui.PerfMonitor._threadStaticCollection", Justification = "[ThreadStatic] cache of a mutable per-thread collection; that is its purpose.")]
[assembly: SuppressMessage("NDepend", "ND1902:AvoidStaticFieldsWithAMutableFieldType", Target = "Stride.CommunityToolkit.ImGui:Stride.CommunityToolkit.ImGui.PerfMonitor._threadStaticMonitor", Justification = "Owner marker for the thread-static cache.")]
